-- PT114-S1-Q16. Batch 12.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT114-S1-Q16$batch12$ AND q.stimulus=$batch12$Policy analyst: Increasing the size of a police force is only a stopgap method of crime prevention; it does not get at the root causes of crime. Therefore, city officials should not respond to rising crime rates by increasing the size of their city’s police force.$batch12$ AND q.prompt=$batch12$The flawed reasoning in which one of the following arguments most closely resembles the flawed reasoning in the policy analyst's argument?$batch12$ AND q.correct_choice=$batch12$D$batch12$) THEN RAISE EXCEPTION 'Question changed: PT114-S1-Q16'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT114-S1-Q16$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT114-S1-Q16'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT114-S1-Q16$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$Officials shouldn't add police to fight rising crime.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$More police is only a stopgap. It doesn't fix the root causes.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$A measure that only treats symptoms can still help. The argument rejects it just because it isn't a complete cure.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Reject a remedy because it doesn't fix the root cause.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT114-S1-Q16$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$The rules are said to make behavior worse. That's a real harm, not just failing to be a cure.$batch12$), ($batch12$B$batch12$, $batch12$Dams are said to worsen the biggest floods. Again, a harm.$batch12$), ($batch12$C$batch12$, $batch12$This recommends a cheaper option after weighing costs.$batch12$), ($batch12$D$batch12$, $batch12$The drug only reduces the disease's worst effects instead of curing it, so the argument says stop prescribing it. Same move.$batch12$), ($batch12$E$batch12$, $batch12$This recommends looking for other approaches, not dropping a partial one.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT114-S1-Q16$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
